#!/usr/bin/env python3
"""Rewrite the auto-generated block of .agents/AGENTS.md with fresh repository data.

The pre-commit hook runs this script, so every commit includes an up-to-date AI
memory file. Only the text between the AUTO markers is replaced. Sections
written by humans or agents are left untouched.

Usage:
    python3 scripts/update_agent_memory.py [--root PATH] [--no-stage] [--no-ai]
"""
from __future__ import annotations

import argparse
import datetime as dt
import sys
from pathlib import Path

from ai_runner import run_ai
from gitutil import git, repo_root

MEMORY_FILE = ".agents/AGENTS.md"
START = "<!-- AGENT-MEMORY:AUTO:START -->"
END = "<!-- AGENT-MEMORY:AUTO:END -->"
STATUS = {
    "A": "added",
    "M": "modified",
    "D": "deleted",
    "R": "renamed",
    "C": "copied",
    "T": "type changed",
}
MAX_DIFF_CHARS = 20_000
MAX_LAYOUT_ENTRIES = 60


def staged_changes(root: Path) -> list[tuple[str, str]]:
    """(status, path) for every staged file except the memory file itself."""
    changes = []
    for line in git(root, "diff", "--cached", "--name-status").splitlines():
        parts = line.split("\t")
        status, path = parts[0][:1], parts[-1]
        if path == MEMORY_FILE:
            continue
        changes.append((STATUS.get(status, status), path))
    return changes


def recent_commits(root: Path, limit: int = 10) -> list[tuple[str, str, str]]:
    """(short sha, date, subject) of the latest commits; empty for a new repo."""
    out = git(root, "log", f"-n{limit}", "--date=short", "--pretty=format:%h|%ad|%s")
    return [tuple(line.split("|", 2)) for line in out.splitlines() if line]


def project_layout(root: Path, depth: int = 2) -> list[str]:
    """Tracked + staged paths, collapsed to ``depth`` levels."""
    entries = set()
    for path in git(root, "ls-files").splitlines():
        parts = path.split("/")
        entries.add("/".join(parts[:depth]) + "/" if len(parts) > depth else path)
    return sorted(entries)


def skills_index(root: Path) -> list[tuple[str, str, str]]:
    """(name, description, relative path) for every SKILL.md under .agents/skills."""
    skills = []
    for skill_file in sorted((root / ".agents" / "skills").glob("*/SKILL.md")):
        meta = parse_frontmatter(skill_file.read_text(encoding="utf-8"))
        name = meta.get("name", skill_file.parent.name)
        skills.append((name, meta.get("description", ""), skill_file.relative_to(root).as_posix()))
    return skills


def parse_frontmatter(text: str) -> dict[str, str]:
    lines = text.splitlines()
    if not lines or lines[0].strip() != "---":
        return {}
    meta = {}
    for line in lines[1:]:
        if line.strip() == "---":
            break
        key, sep, value = line.partition(":")
        if sep:
            meta[key.strip()] = value.strip()
    return meta


def ai_change_summary(root: Path) -> str | None:
    diff = git(root, "diff", "--cached", "--", ".", f":(exclude){MEMORY_FILE}")
    if not diff:
        return None
    prompt = (
        "You maintain AGENTS.md, the shared memory file AI coding agents read before "
        "working on this repository. Summarise the staged change below in at most 5 "
        "Markdown bullet points: what changed, why it matters to a future agent, and "
        "any new convention, command or gotcha. Output only the bullets.\n\n"
        f"```diff\n{diff[:MAX_DIFF_CHARS]}\n```"
    )
    return run_ai(prompt)


def render_block(root: Path, now: dt.datetime, use_ai: bool = True) -> str:
    branch = git(root, "symbolic-ref", "--short", "HEAD") or "detached"
    changes = staged_changes(root)
    lines = [
        START,
        "<!-- Generated by scripts/update_agent_memory.py on every commit. Do not edit by hand. -->",
        "## Auto-generated snapshot",
        "",
        f"_Last updated: {now:%Y-%m-%d %H:%M} UTC · branch `{branch}`_",
        "",
        "### Changes in the latest commit",
    ]
    lines += [f"- {status} `{path}`" for status, path in changes] or ["- (no file changes)"]

    summary = ai_change_summary(root) if use_ai and changes else None
    if summary:
        lines += ["", "### Change summary (AI-generated)", summary]

    lines += ["", "### Recent commits"]
    lines += [f"- `{sha}` {date}: {subject}" for sha, date, subject in recent_commits(root)] or [
        "- (no commits yet)"
    ]

    lines += ["", "### Available skills"]
    lines += [f"- **{name}** (`{path}`): {desc}" for name, desc, path in skills_index(root)] or [
        "- (none)"
    ]

    layout = project_layout(root)
    if len(layout) > MAX_LAYOUT_ENTRIES:
        layout = layout[:MAX_LAYOUT_ENTRIES] + [f"... {len(layout) - MAX_LAYOUT_ENTRIES} more"]
    lines += ["", "### Project layout", "```", *layout, "```", END]
    return "\n".join(lines)


def replace_block(text: str, block: str) -> str:
    """Swap the existing AUTO block for ``block``, or append it if missing."""
    start, end = text.find(START), text.find(END)
    if start != -1 and end > start:
        return text[:start] + block + text[end + len(END):]
    return text.rstrip() + "\n\n" + block + "\n"


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--root", type=Path, default=None)
    parser.add_argument("--no-stage", action="store_true", help="don't git-add the memory file")
    parser.add_argument("--no-ai", action="store_true", help="skip the optional AI summary")
    args = parser.parse_args(argv)

    root = args.root or repo_root()
    memory = root / MEMORY_FILE
    current = memory.read_text(encoding="utf-8") if memory.exists() else "# AGENTS.md\n"
    block = render_block(root, dt.datetime.now(dt.timezone.utc), use_ai=not args.no_ai)
    memory.parent.mkdir(parents=True, exist_ok=True)
    memory.write_text(replace_block(current, block), encoding="utf-8")

    if not args.no_stage:
        git(root, "add", MEMORY_FILE)
    return 0


if __name__ == "__main__":
    sys.exit(main())
